import {escapeHTML as e,imageURL} from './store.js';
import {documentHref} from './document-links.js';
export const chainIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 13 4-4m-6 7-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 1 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/></svg>';
export function mountLinkPreview(editor,documents,openDocument){
 const preview=document.createElement('aside');preview.className='page-link-preview';preview.hidden=true;(editor.closest('dialog')||document.body).append(preview);let timer,active;
 function hide(){timer=setTimeout(()=>{preview.hidden=true;},160);}
 function show(anchor){if(!anchor?.getAttribute('href')?.startsWith('#document/'))return;clearTimeout(timer);let id;try{id=decodeURIComponent(anchor.getAttribute('href').slice(10));}catch{return;}active=documents.find(x=>x.id===id);preview.innerHTML=active?`${imageURL(active.image)?`<img src="${e(imageURL(active.image))}" alt="">`:''}<small>${e(active.label)}</small><strong>${e(active.title)}</strong><p>${e(active.description?.slice(0,200)||'Consulte esta página do seu universo.')}</p><button type="button" class="button ghost">Abrir página ↗</button>`:'<p>Esta página foi removida.</p>';preview.hidden=false;const r=anchor.getBoundingClientRect();preview.style.left=Math.max(12,Math.min(r.left,innerWidth-332))+'px';preview.style.top=Math.max(12,Math.min(r.bottom+8,innerHeight-preview.offsetHeight-12))+'px';preview.querySelector('button')?.addEventListener('click',()=>{preview.hidden=true;openDocument(active.id);});}
 const over=ev=>show(ev.target.closest('a')),out=ev=>{if(ev.target.closest('a'))hide();};editor.addEventListener('pointerover',over);editor.addEventListener('pointerout',out);editor.addEventListener('focusin',over);preview.onpointerenter=()=>clearTimeout(timer);preview.onpointerleave=hide;const scroll=()=>{preview.hidden=true;};window.addEventListener('scroll',scroll,true);
 return()=>{clearTimeout(timer);preview.remove();editor.removeEventListener('pointerover',over);editor.removeEventListener('pointerout',out);editor.removeEventListener('focusin',over);window.removeEventListener('scroll',scroll,true);};
}
export function linkPicker({documents,anchor,selected,onInsert,onRemove,onClose}){
 const dialog=document.createElement('dialog');dialog.className='link-dialog page-link-dialog';let tab=anchor&&!anchor.getAttribute('href')?.startsWith('#document/')?'external':'internal',chosen='';
 try{chosen=decodeURIComponent(anchor?.getAttribute('href')?.slice(10)||'');}catch{}
 dialog.innerHTML=`<form><div class="modal-head"><div><span class="eyebrow">CONECTE SEU UNIVERSO</span><h2>${anchor?'Editar':'Adicionar'} link</h2></div><button type="button" class="icon-button link-close" aria-label="Fechar link">×</button></div><label class="field"><span>Palavra ou texto do link</span><input name="text" maxlength="500" value="${e(selected)}" placeholder="Selecione uma palavra ou escreva aqui"></label><div class="link-tabs"><button type="button" data-link-tab="internal">Página do Aethra</button><button type="button" data-link-tab="external">Link externo</button></div><div data-internal><div class="link-search-row"><input type="search" name="search" placeholder="Buscar qualquer página…" aria-label="Buscar página"><select name="category" aria-label="Categoria"><option value="">Todas as categorias</option>${[...new Set(documents.map(x=>x.type))].map(type=>`<option value="${e(type)}">${e(({home:'Visão geral',notes:'Notas',folder:'Suas pastas',characters:'Personagens',bestiary:'Bestiário',maps:'Atlas',plot:'Trama',scenes:'Cenas',timeline:'Linha do tempo',calendar:'Calendário',connections:'Conexões',globe:'Globo 3D'})[type]||type)}</option>`).join('')}</select></div><div class="link-page-results" role="group" aria-label="Páginas disponíveis"></div><p class="help">Selecione o destino. A palavra continuará dentro do seu texto.</p></div><label class="field" data-external><span>Endereço</span><input name="url" placeholder="https://exemplo.com" value="${e(tab==='external'?anchor?.getAttribute('href')||'':'')}"></label><p class="link-error" role="alert"></p><div class="modal-actions">${anchor?'<button type="button" class="button ghost unlink-button">Remover link</button>':''}<button type="button" class="button ghost link-cancel">Cancelar</button><button class="button" type="submit">${anchor?'Salvar':'Inserir'} link</button></div></form>`;
 document.body.append(dialog);const form=dialog.querySelector('form'),results=dialog.querySelector('.link-page-results');
 function draw(){const q=form.elements.search.value.toLocaleLowerCase('pt-BR'),type=form.elements.category.value;const found=documents.filter(d=>(!type||type===d.type)&&(d.title+' '+d.label).toLocaleLowerCase('pt-BR').includes(q));results.innerHTML=found.map(d=>`<button type="button" data-page="${e(d.id)}" aria-pressed="${chosen===d.id}"><span>${e(d.emoji||'')}</span><span><strong>${e(d.title)}</strong><small>${e(d.label)}</small></span><span>${chosen===d.id?'✓':'↗'}</span></button>`).join('')||'<p class="help">Nenhuma página encontrada.</p>';results.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{chosen=b.dataset.page;draw();});}
 function setTab(t){tab=t;dialog.querySelector('[data-internal]').hidden=t!=='internal';dialog.querySelector('[data-external]').hidden=t!=='external';dialog.querySelectorAll('[data-link-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.linkTab===t)));}
 let closed=false;function close(){if(closed)return;closed=true;dialog.close();dialog.remove();onClose();}
 dialog.querySelector('.link-close').onclick=dialog.querySelector('.link-cancel').onclick=close;dialog.oncancel=ev=>{ev.preventDefault();close();};dialog.querySelector('.unlink-button')?.addEventListener('click',()=>{dialog.close();onRemove();close();});form.elements.search.oninput=form.elements.category.onchange=draw;dialog.querySelectorAll('[data-link-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.linkTab));
 form.onsubmit=ev=>{ev.preventDefault();let href,text=form.elements.text.value.trim();const error=dialog.querySelector('.link-error');if(tab==='internal'){const target=documents.find(d=>d.id===chosen);if(!target){error.textContent='Selecione uma página na lista.';return;}href=documentHref(target.id);text=text||target.title;}else{href=form.elements.url.value.trim();if(!/^[a-z][\w+.-]*:/i.test(href))href='https://'+href;try{const url=new URL(href);if(!['http:','https:','mailto:'].includes(url.protocol)||url.protocol!=='mailto:'&&!url.hostname.includes('.'))throw Error();}catch{error.textContent='Informe um endereço válido.';return;}text=text||href;}dialog.close();onInsert(`<a href="${e(href)}" ${tab==='external'?'target="_blank" rel="noopener noreferrer"':''}>${e(text)}</a>`);close();};draw();setTab(tab);dialog.showModal();return dialog;
}
